"""Sample generation (Section 10.1).

* Sobol points with hash based Owen scrambling and index shuffling (Burley 2020). The first
  four dimensions use the Joe and Kuo direction numbers; later dimensions are padded with
  independently shuffled 2D Sobol pairs, which is the padding scheme of the same paper.
* A 64 x 64 blue noise mask generated by void and cluster (Ulichney 1993) is used as a
  toroidal dither of the pixel and lens sample offsets (Georgiev and Fajardo 2016), so the
  residual error at low sample counts is high frequency.
* Polygonal aperture sampling as a triangle fan (9 blades by default).
"""

from __future__ import annotations

import os
from pathlib import Path

import numpy as np
from numba import njit

MASK32 = np.uint64(0xFFFFFFFF)
INV32 = 1.0 / 4294967296.0

# Joe and Kuo direction numbers (new-joe-kuo-6.21201) for dimensions 1..4; dimension 0 is the
# van der Corput sequence.
_JK = [
    (1, 0, [1]),
    (2, 1, [1, 3]),
    (3, 1, [1, 3, 1]),
    (3, 2, [1, 1, 1]),
]


def _direction_numbers() -> np.ndarray:
    V = np.zeros((5, 32), dtype=np.uint64)
    for k in range(32):
        V[0, k] = np.uint64(1) << np.uint64(31 - k)
    for d, (s, a, m) in enumerate(_JK, start=1):
        v = [0] * 32
        for k in range(s):
            v[k] = m[k] << (32 - (k + 1))
        for k in range(s, 32):
            v[k] = v[k - s] ^ (v[k - s] >> s)
            for i in range(1, s):
                if (a >> (s - 1 - i)) & 1:
                    v[k] ^= v[k - i]
        V[d] = np.array(v, dtype=np.uint64)
    return V


SOBOL_V = _direction_numbers()


@njit(cache=True)
def sobol_u32(index, dim, V):
    """Unscrambled Sobol sample (32 bit integer) for sample ``index`` in dimension ``dim`` (0..4)."""
    x = np.uint64(0)
    i = np.uint64(index)
    k = 0
    while i != 0 and k < 32:
        if i & np.uint64(1):
            x ^= V[dim, k]
        i >>= np.uint64(1)
        k += 1
    return x & MASK32


@njit(cache=True)
def reverse_bits32(x):
    x = x & MASK32
    x = ((x & np.uint64(0x55555555)) << np.uint64(1)) | ((x & np.uint64(0xAAAAAAAA)) >> np.uint64(1))
    x = ((x & np.uint64(0x33333333)) << np.uint64(2)) | ((x & np.uint64(0xCCCCCCCC)) >> np.uint64(2))
    x = ((x & np.uint64(0x0F0F0F0F)) << np.uint64(4)) | ((x & np.uint64(0xF0F0F0F0)) >> np.uint64(4))
    x = ((x & np.uint64(0x00FF00FF)) << np.uint64(8)) | ((x & np.uint64(0xFF00FF00)) >> np.uint64(8))
    x = ((x & np.uint64(0x0000FFFF)) << np.uint64(16)) | ((x & np.uint64(0xFFFF0000)) >> np.uint64(16))
    return x & MASK32


@njit(cache=True)
def laine_karras_permutation(x, seed):
    # Each round is x ^= x * c with an even c, so output bit j equals x_j xor a function of
    # the lower bits: the map is a bijection and, after bit reversal, a nested uniform
    # (Owen) scramble in the sense of Burley (2020).
    x = (x + seed) & MASK32
    x ^= (x * np.uint64(0x6C50B47C)) & MASK32
    x ^= (x * np.uint64(0xB82F1E52)) & MASK32
    x ^= (x * np.uint64(0xC7AFE784)) & MASK32
    x ^= (x * np.uint64(0x8A2D9F6C)) & MASK32
    x ^= (x * np.uint64(0x2A8F3E96)) & MASK32
    return x & MASK32


@njit(cache=True)
def nested_uniform_scramble(x, seed):
    x = reverse_bits32(x)
    x = laine_karras_permutation(x, seed)
    x = reverse_bits32(x)
    return x


@njit(cache=True)
def hash_u32(a, b):
    """Mix two 32 bit values (lowbias32 style)."""
    x = (np.uint64(a) * np.uint64(0x9E3779B1) + np.uint64(b) * np.uint64(0x85EBCA77)) & MASK32
    x ^= x >> np.uint64(16)
    x = (x * np.uint64(0x7FEB352D)) & MASK32
    x ^= x >> np.uint64(15)
    x = (x * np.uint64(0x846CA68B)) & MASK32
    x ^= x >> np.uint64(16)
    return x & MASK32


@njit(cache=True)
def sobol_owen(index, dim, pixel_seed, V):
    """Shuffled, Owen scrambled Sobol sample in [0, 1).

    Dimensions 0..3 share one shuffled index (4D stratification for pixel and lens), later
    dimensions are padded with 2D pairs each with its own index shuffle.
    """
    if dim < 4:
        group = np.uint64(0)
        sdim = dim
    else:
        group = np.uint64(1 + (dim - 4) // 2)
        sdim = (dim - 4) % 2
    idx = nested_uniform_scramble(np.uint64(index), hash_u32(pixel_seed, group))
    x = sobol_u32(idx, sdim, V)
    x = nested_uniform_scramble(x, hash_u32(pixel_seed, np.uint64(1000 + dim)))
    return (float(x) + 0.5) * INV32


@njit(cache=True)
def rng_u01(state):
    """xorshift64* uniform in [0, 1); state is a one element uint64 array."""
    x = state[0]
    x ^= x >> np.uint64(12)
    x ^= x << np.uint64(25)
    x ^= x >> np.uint64(27)
    state[0] = x
    y = (x * np.uint64(0x2545F4914F6CDD1D)) >> np.uint64(11)
    return float(y) * (1.0 / 9007199254740992.0)


@njit(cache=True)
def polygon_aperture_sample(u1, u2, u3, blades):
    """Uniform point in a regular polygon of unit circumradius sampled as a triangle fan.

    Returns (x, y). u1 picks the triangle, (u2, u3) sample it uniformly.
    """
    k = int(u1 * blades)
    if k >= blades:
        k = blades - 1
    a0 = 2.0 * np.pi * k / blades
    a1 = 2.0 * np.pi * (k + 1) / blades
    x0, y0 = np.cos(a0), np.sin(a0)
    x1, y1 = np.cos(a1), np.sin(a1)
    s = np.sqrt(u2)
    b1 = 1.0 - s
    b2 = s * (1.0 - u3)
    b3 = s * u3
    # vertices: apex (0, 0), (x0, y0), (x1, y1)
    return b2 * x0 + b3 * x1, b2 * y0 + b3 * y1


# ------------------------------------------------------------------- blue noise mask


def _void_and_cluster(n: int = 64, sigma: float = 1.5, seed: int = 7) -> np.ndarray:
    """Ulichney's void and cluster algorithm with toroidal Gaussian energy via FFT."""
    rng = np.random.default_rng(seed)
    N = n * n
    yy, xx = np.meshgrid(np.arange(n), np.arange(n), indexing="ij")
    dx = np.minimum(xx, n - xx)
    dy = np.minimum(yy, n - yy)
    kernel = np.exp(-(dx ** 2 + dy ** 2) / (2 * sigma ** 2))
    K = np.fft.rfft2(kernel)

    def energy(binary):
        return np.fft.irfft2(np.fft.rfft2(binary.astype(np.float64)) * K, s=(n, n))

    # initial pattern with about 10 percent ones
    binary = np.zeros((n, n), dtype=bool)
    ones = rng.choice(N, size=N // 10, replace=False)
    binary.flat[ones] = True
    # relax
    for _ in range(N):
        e = energy(binary)
        cluster = np.argmax(np.where(binary, e, -np.inf))
        binary.flat[cluster] = False
        e = energy(binary)
        void = np.argmin(np.where(binary, np.inf, e))
        binary.flat[void] = True
        if void == cluster:
            break
    rank = np.full((n, n), -1, dtype=np.int64)
    # phase 1: remove tightest clusters, rank descending
    b = binary.copy()
    count = int(b.sum())
    while count > 0:
        e = energy(b)
        cluster = np.argmax(np.where(b, e, -np.inf))
        b.flat[cluster] = False
        count -= 1
        rank.flat[cluster] = count
    # phase 2: fill largest voids up to half
    b = binary.copy()
    count = int(b.sum())
    while count < N // 2:
        e = energy(b)
        void = np.argmin(np.where(b, np.inf, e))
        b.flat[void] = True
        rank.flat[void] = count
        count += 1
    # phase 3: invert, continue with the remaining zeros treated as the minority
    inv = ~b
    while count < N:
        e = energy(inv)
        cluster = np.argmax(np.where(inv, e, -np.inf))
        inv.flat[cluster] = False
        rank.flat[cluster] = count
        count += 1
    return (rank.astype(np.float64) + 0.5) / N


_BLUE_NOISE: np.ndarray | None = None


def blue_noise_mask(size: int = 64) -> np.ndarray:
    """Return the (size, size) blue noise mask in [0, 1), generated once and cached on disk."""
    global _BLUE_NOISE
    if _BLUE_NOISE is not None and _BLUE_NOISE.shape[0] == size:
        return _BLUE_NOISE
    path = Path(__file__).parent / "data" / f"bluenoise_{size}.npy"
    if path.exists():
        _BLUE_NOISE = np.load(path)
        return _BLUE_NOISE
    mask = _void_and_cluster(size)
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        np.save(path, mask)
    except OSError:
        pass
    _BLUE_NOISE = mask
    return mask


def sobol_owen_points(n: int, dim: int, seed: int = 0) -> np.ndarray:
    """Python convenience: (n, dim) array of shuffled scrambled Sobol points."""
    out = np.empty((n, dim))
    for i in range(n):
        for d in range(dim):
            out[i, d] = sobol_owen(i, d, np.uint64(seed), SOBOL_V)
    return out
